arguments.new_string:
        if errs:
            # TODO: due to the usage of basic path (not a Path
            # object), the format can be a bit inconsistent here
            # (e.g., 'a.b' and ['a', 'b'])
            raise CheckError(errs, self, scope[Path])
        return ret

    def __repr__(self):
        cn = self.__class__.__name__
        kwargs = {}
        if self.spec is not T:
            kwargs['spec'] = repr(self.spec)
        if self.default is not RAISE:
            kwargs['default'] = repr(self.default)
        if self.types:
            kwargs['type'] = repr(self.types)
        if self.vals:
            kwargs['equal_to'] = repr(self.vals[0]) if len(self.vals) == 1 else repr(self.vals)
        if self.instance_of:
            kwargs['instance_of'] = repr(self.instance_of)
        if self.validators:
            kwargs['validate'] = repr(self.validators)
        kwarg_str = ', '.join(['%s=%s' % (k, v) for k, v in kwargs.items()])
        if kwarg_str:
            return '%s(%s)' % (cn, kwarg_str)
        return '%s()' % cn


